import operator
import re
import sys

_TOKEN = re.compile(r'\s*(?:(\d+)|([A-Z]+\d+)|([A-Z]+)|(<>|<=|>=|[-+*/(),:=<>]))')
_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"
_CMP = {
    '=': operator.eq,
    '<>': operator.ne,
    '<': operator.lt,
    '<=': operator.le,
    '>': operator.gt,
    '>=': operator.ge,
}


def _err(v):
    return isinstance(v, str)


def _tokenize(s):
    tokens = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise ValueError("bad formula: " + s)
        pos = m.end()
        if m.group(1) is not None:
            tokens.append(('num', int(m.group(1))))
        elif m.group(2) is not None:
            tokens.append(('ref', m.group(2)))
        elif m.group(3) is not None:
            tokens.append(('name', m.group(3)))
        else:
            tokens.append(('op', m.group(4)))
    return tokens


def _peek(toks, pos):
    return toks[pos] if pos < len(toks) else (None, None)


def _is_op(toks, pos, ops):
    kind, val = _peek(toks, pos)
    return kind == 'op' and val in ops


def _parse_expr(toks, pos):
    node, pos = _parse_term(toks, pos)
    while _is_op(toks, pos, ('+', '-')):
        op = toks[pos][1]
        right, pos = _parse_term(toks, pos + 1)
        node = ('bin', op, node, right)
    return node, pos


def _parse_term(toks, pos):
    node, pos = _parse_unary(toks, pos)
    while _is_op(toks, pos, ('*', '/')):
        op = toks[pos][1]
        right, pos = _parse_unary(toks, pos + 1)
        node = ('bin', op, node, right)
    return node, pos


def _parse_unary(toks, pos):
    if _is_op(toks, pos, ('-',)):
        node, pos = _parse_unary(toks, pos + 1)
        return ('neg', node), pos
    return _parse_atom(toks, pos)


def _parse_atom(toks, pos):
    kind, val = _peek(toks, pos)
    if kind == 'num':
        return ('num', val), pos + 1
    if kind == 'ref':
        return ('ref', val), pos + 1
    if kind == 'op' and val == '(':
        node, pos = _parse_expr(toks, pos + 1)
        return node, pos + 1  # skip ')'
    if kind == 'name':
        pos += 2  # skip name and '('
        if val == 'IF':
            left, pos = _parse_expr(toks, pos)
            op = toks[pos][1]
            right, pos = _parse_expr(toks, pos + 1)
            then, pos = _parse_expr(toks, pos + 1)
            els, pos = _parse_expr(toks, pos + 1)
            return ('if', op, left, right, then, els), pos + 1  # skip ')'
        args = []
        while True:
            k, v = _peek(toks, pos)
            if k == 'ref' and _is_op(toks, pos + 1, (':',)):
                args.append(('range', v, toks[pos + 2][1]))
                pos += 3
            else:
                arg, pos = _parse_expr(toks, pos)
                args.append(arg)
            if _is_op(toks, pos, (',',)):
                pos += 1
                continue
            break
        return (val.lower(), args), pos + 1  # skip ')'
    raise ValueError("unexpected token")


def _range_names(a, b):
    ca, ra = ord(a[0]) - 65, int(a[1:])
    cb, rb = ord(b[0]) - 65, int(b[1:])
    for r in range(min(ra, rb), max(ra, rb) + 1):
        for c in range(min(ca, cb), max(ca, cb) + 1):
            yield chr(65 + c) + str(r)


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    parsed = {}
    for name, content in cells.items():
        text = content.strip()
        if text.startswith('='):
            toks = _tokenize(text[1:])
            node, _ = _parse_expr(toks, 0)
            parsed[name] = node
        else:
            parsed[name] = ('num', int(text))

    values = {}
    busy = set()

    def get(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in busy:
            return _CYCLE
        busy.add(name)
        v = ev(parsed[name])
        busy.discard(name)
        values[name] = v
        return v

    def ev(node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return get(node[1])
        if kind == 'neg':
            v = ev(node[1])
            return v if _err(v) else -v
        if kind == 'bin':
            op = node[1]
            l = ev(node[2])
            if _err(l):
                return l
            r = ev(node[3])
            if _err(r):
                return r
            if op == '+':
                return l + r
            if op == '-':
                return l - r
            if op == '*':
                return l * r
            if r == 0:
                return _DIV0
            q = abs(l) // abs(r)
            return q if (l < 0) == (r < 0) else -q
        if kind == 'if':
            l = ev(node[2])
            if _err(l):
                return l
            r = ev(node[3])
            if _err(r):
                return r
            branch = node[4] if _CMP[node[1]](l, r) else node[5]
            return ev(branch)
        # SUM, MIN, MAX
        vals = []
        for arg in node[1]:
            if arg[0] == 'range':
                for name in _range_names(arg[1], arg[2]):
                    if name not in cells:
                        continue
                    v = get(name)
                    if _err(v):
                        return v
                    vals.append(v)
            else:
                v = ev(arg)
                if _err(v):
                    return v
                vals.append(v)
        if not vals:
            return 0
        if kind == 'sum':
            return sum(vals)
        if kind == 'min':
            return min(vals)
        return max(vals)

    return {name: get(name) for name in cells}
